_rewards'''\n\ncontent = re.sub(pattern, replacement, content, flags=re.DOTALL)\n\nwith open('/root/SimPO/scripts/simpo_trainer.py', 'w') as f:\n    f.write(content)\n\nprint('Updated simpo_loss function')\nPYEOF\n",
