      "keystrokes": "python3 << 'PYEOF'\nimport re\n\nwith open('/root/SimPO/scripts/simpo_trainer.py', 'r') as f:\n    content = f.read()\n\n# Find the simpo_loss function and replace it\npattern = r'def simpo_loss\\(self.*?\\):\\s*pass'\nreplacement = '''def simpo_loss(\n        self,\n        policy_chosen_logps,\n        policy_rejected_logps,\n        reference_chosen_logps=None,\n        reference_rejected_logps=None,\n        beta=0.5,\n        gamma=1.0,\n    ):\n        \"\"\"\n        Compute SimPO loss.\n        \n        Args:\n            policy_chosen_logps: Log probabilities of chosen responses from policy model\n            policy_rejected_logps: Log probabilities of rejected responses from policy model\n            reference_chosen_logps: Log probabilities of chosen responses from reference model\n            reference_rejected_logps: Log probabilities of rejected responses from reference model\n            beta: Temperature parameter (default: 0.5)\n            gamma: Margin parameter (default: 1.0)\n            \n        Returns:\n            Tuple of (losses, chosen_rewards, rejected_rewards)\n        \"\"\"\n        # Calculate policy log ratios\n        policy_logratios = policy_chosen_logps - policy_rejected_logps\n        \n        # If reference logps are provided, use them; otherwise assume zero\n        if reference_chosen_logps is None:\n            reference_logratios = torch.zeros_like(policy_logratios)\n        else:\n            reference_logratios = reference_chosen_logps - reference_rejected_logps\n        \n        # Calculate logits for sigmoid\n        logits = policy_logratios - reference_logratios\n        \n        # SimPO loss: -log(sigmoid(beta * (logits - gamma)))\n        losses = -F.logsigmoid(beta * (logits - gamma))\n        \n        # Calculate rewards\n        chosen_rewards = beta * policy_chosen_logps\n        rejected_rewards = beta * policy_rejected_logps\n        \n        return losses, chosen_rewards, rejected_rewards'''\n\ncontent = re.sub(pattern, replacement, content, flags=re.DOTALL)\n\nwith open('/root/SimPO/scripts/simpo_trainer.py', 'w') as f:\n    f.write(content)\n\nprint('Updated simpo_loss function')\nPYEOF\n",
